def word_count(text: str) -> int:
    """Count non-empty words in text."""
    return len(text.split(' '))  # bug: split(' ') creates empty tokens on multiple spaces

def reverse_words(text: str) -> str:
    """Reverse the order of words in text."""
    return text[::-1]  # bug: reverses characters, not word order

def capitalize_words(text: str) -> str:
    """Capitalise the first letter of each word, lowercase the rest."""
    return text.upper()  # bug: uppercases all characters

