from src.textproc import word_count, reverse_words, capitalize_words

def test_word_count_basic():
    assert word_count("hello world") == 2

def test_word_count_extra_spaces():
    assert word_count("hello  world") == 2

def test_reverse_words():
    assert reverse_words("hello world foo") == "foo world hello"

def test_capitalize_words():
    assert capitalize_words("hello WORLD foo") == "Hello World Foo"

def test_word_count_empty():
    assert word_count("") == 0
